package kr.workbench;
import burp.api.montoya.*;import burp.api.montoya.http.*;import burp.api.montoya.http.message.*;import burp.api.montoya.http.message.requests.*;import burp.api.montoya.internal.*;import javax.swing.*;import javax.swing.table.*;import java.nio.file.*;import java.util.*;import java.util.List;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** CLI fixtures and Burp API adapters. No external archive or target traffic. */
public class PassiveScanTest extends WorkbenchTest {
 static void idle(PassiveScanPanel p)throws Exception{for(int i=0;i<800;i++){edt(()->{});if(p.job==null)return;Thread.sleep(10);}throw new AssertionError("passive job timeout");}
 public static void main(String[] args)throws Exception{
  check(PassiveUrls.domain("https://Example.COM/path?q=1").equals("example.com"),"domain extracted from HTTP URL");for(String invalid:List.of("example.com;id","$(id)","-x","example..com","https://user@example.com")){try{PassiveUrls.domain(invalid);throw new AssertionError();}catch(IllegalArgumentException e){check(true,"invalid CLI domain rejected: "+invalid);}}
  check(PassiveUrls.url("https://example.com/a%2Fb?q=%25#section","example.com",false).equals("https://example.com/a%2Fb?q=%25"),"escaped path and query preserved; fragment removed");check(PassiveUrls.url("https://sub.example.com/a","example.com",false)==null&&PassiveUrls.url("https://sub.example.com/a","example.com",true)!=null,"subdomain setting enforced");check(PassiveUrls.url("https://example.com.evil/a","example.com",true)==null&&PassiveUrls.url("javascript:alert(1)","example.com",true)==null,"unrelated hosts and non-HTTP links excluded");check(PassiveUrls.command("waybackurls","/path with spaces/wb",false).equals(List.of("/path with spaces/wb","-no-subs")),"executable path passed without shell");check(PassiveUrls.command("gau","gau",true).contains("--subs"),"gau actual flags include requested subdomains");
  Path directory=Files.createTempDirectory("passive cli "),cli=NativeCliFixture.create(directory.resolve("fixture"),"multi");List<String> collected=new ArrayList<>();PassiveUrls.collect("gau",cli.toString(),"example.com",false,new AtomicBoolean(),p->{},collected::add);check(collected.size()==3&&!collected.toString().contains("other.test"),"actual subprocess stdin/stdout adapter filters output");Path broken=NativeCliFixture.create(directory.resolve("failed"),"failed");try{PassiveUrls.collect("waybackurls",broken.toString(),"example.com",false,new AtomicBoolean(),p->{},u->{});throw new AssertionError();}catch(java.io.IOException e){check(e.getMessage().contains("7")&&e.getMessage().contains("fixture-error"),"CLI nonzero exit and stderr surfaced");}
  AtomicInteger sent=new AtomicInteger(),timeout=new AtomicInteger();AtomicReference<RedirectionMode> redirects=new AtomicReference<>();AtomicBoolean scope=new AtomicBoolean(true);AtomicReference<CountDownLatch> wait=new AtomicReference<>();CountDownLatch entered=new CountDownLatch(1);
  ObjectFactoryLocator.FACTORY=proxy(MontoyaObjectFactory.class,(p,m,a)->switch(m.getName()){case "httpRequestFromUrl"->request((String)a[0],"GET",scope.get()&&!((String)a[0]).contains("/outside"),List.of());case "requestOptions"->proxy(RequestOptions.class,(pp,mm,aa)->{if(mm.getName().equals("withResponseTimeout"))timeout.set(((Number)aa[0]).intValue());if(mm.getName().equals("withRedirectionMode"))redirects.set((RedirectionMode)aa[0]);return pp;});default->def(m);});
  var http=proxy(Http.class,(p,m,a)->{if(!m.getName().equals("sendRequest"))return def(m);HttpRequest q=(HttpRequest)a[0];check(!SwingUtilities.isEventDispatchThread()&&q.method().equals("GET"),"verification GET runs off EDT");sent.incrementAndGet();if(wait.get()!=null){entered.countDown();wait.get().await(2,TimeUnit.SECONDS);}if(q.url().contains("/error"))throw new java.io.IOException("fixture");var s=response(q.url().contains("/b")?403:200,"{\"nested\":{\"ok\":true}}");return proxy(HttpRequestResponse.class,(pp,mm,aa)->switch(mm.getName()){case "request"->q;case "response"->s;default->def(mm);});});MontoyaApi api=proxy(MontoyaApi.class,(p,m,a)->m.getName().equals("http")?http:def(m));AtomicReference<PassiveScanPanel> box=new AtomicReference<>();edt(()->box.set(new PassiveScanPanel(api)));PassiveScanPanel panel=box.get();
  edt(()->{panel.target.setText("example.com");panel.waybackPath.setText(cli.toString());panel.gauPath.setText(cli.toString());panel.collect();});idle(panel);edt(()->{check(panel.items.size()==2&&panel.model.getValueAt(0,2).toString().contains("waybackurls + gau"),"two CLI sources merged with URL deduplication");panel.table.setRowSelectionInterval(0,0);check(sent.get()==0&&panel.response.text.getText().contains("미검증"),"collect/select sends no target requests");panel.single.doClick();});idle(panel);check(sent.get()==1&&panel.packets.size()==1,"single start sends one selected URL");edt(()->check(panel.response.text.getText().contains("\n  \"nested\""),"selected response structured JSON"));edt(()->panel.batch.doClick());idle(panel);check(sent.get()==3&&timeout.get()==10000&&redirects.get()==RedirectionMode.NEVER,"batch sends all visible URLs with bounded nonredirecting requests");
  edt(()->{((TableRowSorter<?>)panel.table.getRowSorter()).setSortKeys(List.of(new RowSorter.SortKey(1,SortOrder.DESCENDING)));panel.table.setRowSelectionInterval(0,0);check(panel.selected().contains("/b")&&panel.response.text.getText().contains("403"),"sorted row resolves matching request/response");panel.importUrls("https://example.com/outside\n");panel.verify(panel.visible());check(panel.job==null,"out-of-scope batch rejected before requests");});check(sent.get()==3,"scope rejection emits no requests");
  edt(()->{panel.importUrls("https://example.com/error\n");panel.verify(List.of("https://example.com/error"));});idle(panel);edt(()->check(panel.items.get("https://example.com/error").state.equals("전송 오류"),"transport error stored in status"));
  wait.set(new CountDownLatch(1));edt(()->panel.verify(List.of("https://example.com/a","https://example.com/b?q=1")));check(entered.await(2,TimeUnit.SECONDS),"first batch request entered");edt(panel::stop);wait.get().countDown();idle(panel);check(sent.get()==5,"stop prevents subsequent sends");
  edt(()->{StringBuilder many=new StringBuilder();for(int i=0;i<1100;i++)many.append("https://example.com/limit/").append(i).append('\n');panel.importUrls(many.toString());check(panel.items.size()==PassiveUrls.LIMIT,"passive URL retention bounded");panel.close();panel.verify(List.of("https://example.com/a"));check(panel.items.isEmpty()&&panel.packets.isEmpty()&&panel.job==null,"unload clears data and prevents jobs");});Files.deleteIfExists(cli);Files.deleteIfExists(broken);Files.deleteIfExists(directory);System.out.println("PassiveScanTest: "+checks+" checks passed");
 }
}
